    localparam logic [2:0] A  = 3'd0; // reset/idle
    localparam logic [2:0] B  = 3'd1; // one-cycle f pulse
    localparam logic [2:0] C0 = 3'd2; // waiting for x=1
    localparam logic [2:0] C1 = 3'd3; // waiting for x=0
    localparam logic [2:0] C2 = 3'd4; // waiting for x=1 (3rd of pattern)
    localparam logic [2:0] D  = 3'd5; // g asserted (window cycle 1)
    localparam logic [2:0] D1 = 3'd6; // g asserted (window cycle 2)
    localparam logic [2:0] E  = 3'd7; // g permanently 1

