    // Since we used 3-bit encoding, we need another state; remap to keep within 3 bits.
    // We'll instead treat state A as permanent 0 after failure (until reset). 

    logic [2:0] state, state_next;

    // Sequential state update (synchronous active-low reset)
    always_ff @(posedge clk) begin
        if (!resetn) begin
            state <= A;
        end else begin
            state <= state_next;
        end
    end

    // Next-state combinational logic
    always @(*) begin
        state_next = state;
        case (state)
            A: begin
                // After reset deasserts, go to B to pulse f on next clock
                state_next = B;
            end

            B: begin
                // After one cycle, start monitoring x pattern
                state_next = C0;
            end

            C0: begin
                // Expect x=1
                if (x) state_next = C1;
                else    state_next = C0;
            end

            C1: begin
                // Expect x=0
                if (!x) state_next = C2;
                else begin
                    // x==1: this can start a new pattern at the first element
                    state_next = C1;
                end
            end

            C2: begin
                // Expect x=1 (third of pattern)
                if (x) state_next = D; // g asserted on this next cycle via D state
                else begin
                    // If x==0, pattern breaks; go back to waiting for first '1'
                    state_next = C0;
                end
            end

            D: begin
                // g is 1 during D. Check y within 2 cycles total.
                if (y) state_next = E; // success
                else   state_next = D1; // second window cycle
            end

            D1: begin
                // If y still not 1, g becomes 0 permanently (until reset)
                if (y) state_next = E;
                else   state_next = A; // permanent 0 behavior until reset
            end

            E: begin
                // g permanently 1 until reset
                state_next = E;
            end

            default: begin
                state_next = A;
            end
        endcase
    end

