    localparam logic [2:0] A   = 3'd0; // idle/reset, f=0,g=0 (after resetn deassert, next clock goes to B)
    localparam logic [2:0] B   = 3'd1; // pulse f=1 for one cycle
    localparam logic [2:0] S0  = 3'd2; // wait for x=1 (1st element)
    localparam logic [2:0] S1  = 3'd3; // wait for x=0 (2nd element)
    localparam logic [2:0] S2  = 3'd4; // wait for x=1 (3rd element)
    localparam logic [2:0] Y0  = 3'd5; // g=1, y window cycle 1
    localparam logic [2:0] Y1  = 3'd6; // g=1, y window cycle 2
    localparam logic [2:0] G1  = 3'd7; // g permanently 1 until reset

