    always @(*) begin
        state_next = state;
        unique case (state)
            A: begin
                // After reset deasserts, next clock must go to B to assert f for one cycle
                state_next = B;
            end

            B: begin
                // Then start monitoring x pattern
                state_next = S0;
            end

            S0: begin
                // Expect first '1'
                state_next = (x) ? S1 : S0;
            end

            S1: begin
                // Expect second '0'
                // If x==1 here, it can start a new pattern immediately as the first element
                if (!x) state_next = S2;
                else    state_next = S1; // treat this cycle as the first element seen
            end

            S2: begin
                // Expect third '1'
                // If x==1, g must be asserted on the following clock cycle => go to Y0 now
                if (x) state_next = Y0;
                else   state_next = S0;
            end

            Y0: begin
                // g is 1 in Y0. If y==1 within this cycle, then g becomes permanent.
                // Otherwise advance to second y window cycle.
                state_next = (y) ? G1 : Y1;
            end

            Y1: begin
                // g is 1 in Y1. If y==1 in this cycle, become permanent 1.
                // If y==0 in this cycle, then g becomes permanent 0 (until reset).
                state_next = (y) ? G1 : A;
            end

            G1: begin
                // Permanent g=1
                state_next = G1;
            end

            default: begin
                state_next = A;
            end
        endcase
    end

    // Output decode (Moore)
    always @(*) begin
        f = 1'b0;
        g = 1'b0;
        case (state)
            B:  begin
                f = 1'b1;
                g = 1'b0;
            end
            Y0, Y1: begin
                f = 1'b0;
                g = 1'b1;
            end
            G1: begin
                f = 1'b0;
                g = 1'b1;
            end
            default: begin
                f = 1'b0;
                g = 1'b0;
            end
        endcase
    end

    // Initialize state for known behavior in case reset is not asserted at time 0
    initial begin
        state = A;
    end
"
  }
}

